import config_system as cs

errors = []

# --- F1: log_level allowed ---
schema = cs.get_schema()
allowed = schema['log_level']['allowed']
if allowed != {'INFO', 'WARN', 'ERROR'}:
    errors.append(f'F1 FAIL: allowed={allowed}')
else:
    print('F1 PASS: log_level allowed = {\"INFO\", \"WARN\", \"ERROR\"}')

# Verify DEBUG/FATAL rejected
try:
    cs.validate_value('log_level', 'DEBUG')
    errors.append('F1 FAIL: DEBUG should be rejected')
except cs.ConfigValidationError:
    print('F1 PASS: DEBUG correctly rejected')
try:
    cs.validate_value('log_level', 'FATAL')
    errors.append('F1 FAIL: FATAL should be rejected')
except cs.ConfigValidationError:
    print('F1 PASS: FATAL correctly rejected')

# Verify INFO/WARN/ERROR accepted
for v in ('INFO', 'WARN', 'ERROR'):
    try:
        result = cs.validate_value('log_level', v)
        if result != v:
            errors.append(f'F1 FAIL: {v} result mismatch')
        else:
            print(f'F1 PASS: {v} accepted')
    except cs.ConfigValidationError:
        errors.append(f'F1 FAIL: {v} should be accepted')

# --- F6: bool empty string ---
try:
    cs.validate_value('debug_mode', '')
    errors.append('F6 FAIL: empty string should raise error')
except cs.ConfigValidationError as e:
    print(f'F6 PASS: empty string correctly rejected: {e}')

# Verify normal bool values still work
for v, expected in [('true', True), ('True', True), ('false', False), ('False', False), 
                     ('1', True), ('0', False), ('yes', True), ('no', False),
                     ('on', True), ('off', False), (True, True), (False, False)]:
    try:
        result = cs.validate_value('debug_mode', v)
        if result != expected:
            errors.append(f'F6 FAIL: {v!r} -> {result}, expected {expected}')
    except cs.ConfigValidationError:
        errors.append(f'F6 FAIL: {v!r} should be valid')

print('F6 PASS: all valid bool values work correctly')

# --- load_config smoke test ---
config = cs.load_config()
assert config['log_level'] == 'WARN'
assert config['debug_mode'] == False
print('load_config defaults PASS')

# env override
config = cs.load_config(env_vars={'WEB_LOG_LEVEL': 'ERROR', 'WEB_DEBUG': 'true'})
assert config['log_level'] == 'ERROR'
assert config['debug_mode'] == True
print('load_config env override PASS')

# cli override
config = cs.load_config(cli_args={'log_level': 'INFO', 'debug_mode': False})
assert config['log_level'] == 'INFO'
assert config['debug_mode'] == False
print('load_config cli override PASS')

if errors:
    print('\nERRORS:')
    for e in errors:
        print(f'  {e}')
else:
    print('\n=== ALL TESTS PASSED ===')
